function headingsFromQuarto(markdown:string){
 let fenced=false;const result:{level:number;text:string}[]=[];
 for(const row of markdown.replace(/\r\n?/g,"\n").split("\n")){
  if(/^\s{0,3}(?:\x60{3,}|~{3,})/.test(row)){fenced=!fenced;continue}
  if(fenced)continue;
  const match=row.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);
  if(match){const title=match[2].replace(/\s+\{[^{}]*\}\s*$/,"").replace(/[*_]/g,"").trim();if(title)result.push({level:match[1].length,text:title});}
 }return result;
}
