function targetFor(book:Book,wanted:number){
 const stages=book.stageReadiness?.stages||[];
 let target=wanted;
 while(target>0&&!stages[target]?.available)target--;
 return target;
}
function jumpToProblem(book:Book,index:number){
 const target=targetFor(book,index);
 const modules=["Proyek Buku","Rancang","Studio Penulisan"] as const;
 const needed=book.stageReadiness?.stages[target]?.missing??[];
 const statement=target!==index
  ?"Tahap yang dipilih belum tersedia. Lengkapi tahap sebelumnya terlebih dahulu."
  :index===0?"Lengkapi data buku yang ditandai, lalu simpan perubahan."
  :index===1?"Lengkapi judul dan tujuan setiap bab sebelum melanjutkan ke penulisan."
  :"Lengkapi isi naskah setiap bab, lalu pastikan perubahan tersimpan.";
 setStageGuide(statement);
 jumpRef.current={bookId:book.id,module:modules[target],index:target,missing:needed};
 setJumpSerial(n=>n+1);
 if(id!==book.id)selectProject(book);
 onNavigate(modules[target],book.id);
}
useEffect(()=>{
 const pending=jumpRef.current;
 if(!pending||pending.bookId!==id||pending.module!==active)return;
 let tries=0;
 const focus=()=>{
  const request=jumpRef.current;
  if(!request||request!==pending)return;
  let element:HTMLElement|null=null;
  if(request.index===0){
   const all=[...document.querySelectorAll("label.studio-field")];
   const targets=[["Judul buku","Judul buku"],["Bidang buku","Mata pelajaran"],["Sinopsis","Brief / deskripsi buku"],["Pembaca sasaran","Pembaca sasaran"],["Tujuan penulisan","Tujuan penulisan"],["Penulis","Penulis"],["Genre","Genre"],["Jenis buku","Jenis buku"]];
   const match=targets.find(([key])=>request.missing.some(m=>m.includes(key)));
   if(!match&&request.missing.some(m=>m.includes("Lanjut ke Rancang"))) {
    element=document.querySelector('[aria-label="Tahap Ide"] .stage-primary-actions button');
   }else{
    const label=all.find(e=>(e.textContent||"").trim().startsWith(match?.[1]||"Judul buku"));
    element=label?.querySelector("input,textarea,select")??null;
   }
  }else if(request.index===1){
   const incomplete=document.querySelector(".chapter-status-card.status-red,.chapter-status-card.status-yellow");
   const edit=[...(incomplete?.querySelectorAll("button")??[])].find(b=>b.textContent?.trim()==="Ubah kerangka") as HTMLButtonElement|undefined;
   if(edit)edit.click();
   element=edit?document.querySelector('[aria-label="Tahap Rancang"] textarea'):document.querySelector('[aria-label="Tahap Rancang"] input[placeholder]');
   element??=document.querySelector('[aria-label="Tahap Rancang"] input[placeholder]');
  }else{
   element=document.querySelector('[aria-label="Kanvas naskah draf"] textarea')??document.querySelector('[aria-label="Kanvas naskah draf"] select');
  }
  if(!element&&tries++<15){setTimeout(focus,120);return}
  const current=element;
  if(current){current.scrollIntoView({behavior:"smooth",block:"center"});current.focus({preventScroll:true})}
  jumpRef.current=null;
 };
 const timer=setTimeout(focus,160);
 return()=>clearTimeout(timer);
},[active,id,books,jumpSerial]);

