async function restoreChapter(chapterId:string,revision:number){
 if(dirty||busy||autoSavingRef.current||!historyVersion)return;
 if(!confirm("Pulihkan versi "+revision+"? Isi saat ini tetap disimpan dalam riwayat."))return;
 await run(async()=>{
  try{
   const {chapter:restored,unchanged}=await(await api("/books/"+id+"/chapters/"+chapterId,{
    method:"PATCH",body:JSON.stringify({restoreRevision:revision,expectedVersion:historyVersion}),
   })).json();
   if(latestDraftRef.current.id===id&&latestDraftRef.current.editChapterId===chapterId){
    setChapter(restored.title);
    setText(restored.content);
    setChapterVersion(restored.updatedAt);
   }
   await loadChapterHistory(chapterId);
   setNotice(unchanged?"Bab sudah memakai isi versi tersebut.":"Revisi dipulihkan. Isi sebelumnya tersimpan dalam riwayat.");
  }catch(error){
   if(error instanceof Error&&"code" in error&&error.code==="CHAPTER_VERSION_CONFLICT"){
    await loadChapterHistory(chapterId);
    throw Error("Bab telah berubah. Riwayat dimuat ulang. Periksa versi sebelum mencoba lagi.");
   }
   throw error;
  }
 });
}
